#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> par(n);
    for (int i = 0; i < n; i++) cin >> par[i];
    string s;
    cin >> s;

    int count = (int)n;
    vector<vector<int>> kids(count + 1);
    int root = 0;
    for (int v = 1; v <= count; v++) {
        if (par[v - 1] == 0) root = v;
        else kids[par[v - 1]].push_back(v);
    }
    vector<int> order = {root};
    for (size_t i = 0; i < order.size(); i++) {
        for (int c : kids[order[i]]) order.push_back(c);
    }
    vector<int> m1(count + 1, 0), m2(count + 1, 0);
    int best = 1;
    for (size_t i = order.size(); i-- > 0;) {
        int v = order[i];
        best = max(best, 1 + m1[v] + m2[v]);
        int chain = 1 + m1[v];
        int p = (int)par[v - 1];
        if (p != 0 && s[v - 1] != s[p - 1]) {
            if (chain > m1[p]) {
                m2[p] = m1[p];
                m1[p] = chain;
            } else if (chain > m2[p]) {
                m2[p] = chain;
            }
        }
    }
    cout << best << "\n";

    return 0;
}

