import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] par = new long[(int) n];
        for (int i = 0; i < par.length; i++) par[i] = Long.parseLong(next());
        String s = next();

        int count = (int) n;
        List<List<Integer>> kids = new ArrayList<>();
        for (int v = 0; v <= count; v++) kids.add(new ArrayList<>());
        int root = 0;
        for (int v = 1; v <= count; v++) {
            if (par[v - 1] == 0) root = v;
            else kids.get((int) par[v - 1]).add(v);
        }
        List<Integer> order = new ArrayList<>();
        order.add(root);
        for (int i = 0; i < order.size(); i++) order.addAll(kids.get(order.get(i)));
        int[] m1 = new int[count + 1];
        int[] m2 = new int[count + 1];
        int best = 1;
        for (int i = order.size() - 1; i >= 0; i--) {
            int v = order.get(i);
            best = Math.max(best, 1 + m1[v] + m2[v]);
            int chain = 1 + m1[v];
            int p = (int) par[v - 1];
            if (p != 0 && s.charAt(v - 1) != s.charAt(p - 1)) {
                if (chain > m1[p]) {
                    m2[p] = m1[p];
                    m1[p] = chain;
                } else if (chain > m2[p]) {
                    m2[p] = chain;
                }
            }
        }
        System.out.println(best);
    }
}
